import io
import gzip
import base64
import pandas as pd

# 309-scan clinically validated reference baseline
VERA_B64 = """"""


def get_baseline_dataframe():
    """Returns the 309-scan clinically validated reference baseline."""
    raw_csv = gzip.decompress(base64.b64decode(VERA_B64.encode())).decode("utf-8")
    df = pd.read_csv(io.StringIO(raw_csv))
    return df
